+import { Context, Effect, Option, Schema } from "effect";
+import * as KeyValueStore from "effect/unstable/persistence/KeyValueStore";
+
+import {
+  OAuthProfileNotFound,
+  OAuthProfileSchemaError,
+  OAuthProfileStorageError,
+} from "./errors.js";
+import type { CodexProfileStoreFailure } from "./errors.js";
+import {
+  codexOAuthProfileStorageKey,
+  codexOAuthProfileSubjectHash,
+} from "./storage-keys.js";
+import { CodexOAuthProfile } from "./schemas.js";
+import type {
+  CodexOAuthProfile as CodexOAuthProfileType,
+  CodexOAuthSubject,
+} from "./schemas.js";
+
+export interface CodexProfileStoreShape {
+  readonly getProfile: (
+    subject: CodexOAuthSubject
+  ) => Effect.Effect<CodexOAuthProfileType, CodexProfileStoreFailure>;
+  readonly putProfile: (
+    profile: CodexOAuthProfileType
+  ) => Effect.Effect<void, CodexProfileStoreFailure>;
+  readonly removeProfile: (
+    subject: CodexOAuthSubject
+  ) => Effect.Effect<void, CodexProfileStoreFailure>;
+  readonly hasProfile: (
+    subject: CodexOAuthSubject
+  ) => Effect.Effect<boolean, CodexProfileStoreFailure>;
+}
+
+export class CodexProfileStore extends Context.Service<
+  CodexProfileStore,
+  CodexProfileStoreShape
+>()("@bundjil/codex-oauth/CodexProfileStore") {}
+
+export const CodexProfileStoreLive = Effect.gen(function* makeStore() {
+  const keyValueStore = yield* KeyValueStore.KeyValueStore;
+  const schemaStore = KeyValueStore.toSchemaStore(
+    keyValueStore,
+    CodexOAuthProfile
+  );
+
+  return CodexProfileStore.of({
+    getProfile: (subject) =>
+      Effect.gen(function* getProfile() {
+        const key = yield* codexOAuthProfileStorageKey(subject);
+        const subjectHash = yield* codexOAuthProfileSubjectHash(subject);
+        const profile = yield* schemaStore.get(key).pipe(
+          Effect.catchTag(
+            "KeyValueStoreError",
+            (cause) =>
+              new OAuthProfileStorageError({
+                operation: "getProfile",
+                key,
+                message: "Unable to read Codex OAuth profile.",
+                cause,
+              })
+          ),
+          Effect.catchTag(
+            "SchemaError",
+            (cause) =>
+              new OAuthProfileSchemaError({
+                boundary: "CodexOAuthProfile",
+                message: "Unable to decode Codex OAuth profile.",
+                cause,
+              })
+          )
+        );
+
+        if (Option.isNone(profile)) {
+          return yield* Effect.fail(
+            new OAuthProfileNotFound({
+              profileId: subject.profileId,
+              subjectHash,
+              message: "Codex OAuth profile was not found.",
+            })
+          );
+        }
+
+        return profile.value;
+      }).pipe(Effect.withSpan("CodexProfileStore.getProfile")),
+    putProfile: (profile) =>
+      Effect.gen(function* putProfile() {
+        const key = yield* codexOAuthProfileStorageKey(profile.subject);
+
+        yield* schemaStore.set(key, profile).pipe(
+          Effect.catchTag(
+            "KeyValueStoreError",
+            (cause) =>
+              new OAuthProfileStorageError({
+                operation: "putProfile",
+                key,
+                message: "Unable to store Codex OAuth profile.",
+                cause,
+              })
+          ),
+          Effect.catchTag(
+            "SchemaError",
+            (cause) =>
+              new OAuthProfileSchemaError({
+                boundary: "CodexOAuthProfile",
+                message: "Unable to encode Codex OAuth profile.",
+                cause,
+              })
+          )
+        );
+      }).pipe(Effect.withSpan("CodexProfileStore.putProfile")),
+    removeProfile: (subject) =>
+      Effect.gen(function* removeProfile() {
+        const key = yield* codexOAuthProfileStorageKey(subject);
+
+        yield* schemaStore.remove(key).pipe(
+          Effect.catchTag(
+            "KeyValueStoreError",
+            (cause) =>
+              new OAuthProfileStorageError({
+                operation: "removeProfile",
+                key,
+                message: "Unable to remove Codex OAuth profile.",
+                cause,
+              })
+          )
+        );
+      }).pipe(Effect.withSpan("CodexProfileStore.removeProfile")),
+    hasProfile: (subject) =>
+      Effect.gen(function* hasProfile() {
+        const key = yield* codexOAuthProfileStorageKey(subject);
+
+        return yield* schemaStore.has(key).pipe(
+          Effect.catchTag(
+            "KeyValueStoreError",
+            (cause) =>
+              new OAuthProfileStorageError({
+                operation: "hasProfile",
+                key,
+                message: "Unable to check Codex OAuth profile.",
+                cause,
+              })
+          )
+        );
+      }).pipe(Effect.withSpan("CodexProfileStore.hasProfile")),
+  });
+}).pipe(Effect.withSpan("CodexProfileStoreLive"));
+
+export const getProfile = (subject: CodexOAuthSubject) =>
+  Effect.gen(function* getProfileOperation() {
+    const store = yield* CodexProfileStore;
+
+    return yield* store.getProfile(subject);
+  });
+
+export const putProfile = (profile: CodexOAuthProfileType) =>
+  Effect.gen(function* putProfileOperation() {
+    const store = yield* CodexProfileStore;
+
+    yield* Schema.encodeEffect(CodexOAuthProfile)(profile).pipe(
+      Effect.mapError(
+        (cause) =>
+          new OAuthProfileSchemaError({
+            boundary: "CodexOAuthProfile",
+            message: "Unable to encode Codex OAuth profile.",
+            cause,
+          })
+      )
+    );
+
+    return yield* store.putProfile(profile);
+  });
+
+export const removeProfile = (subject: CodexOAuthSubject) =>
+  Effect.gen(function* removeProfileOperation() {
+    const store = yield* CodexProfileStore;
+
+    return yield* store.removeProfile(subject);
+  });
+
+export const hasProfile = (subject: CodexOAuthSubject) =>
+  Effect.gen(function* hasProfileOperation() {
+    const store = yield* CodexProfileStore;
+
+    return yield* store.hasProfile(subject);
+  });
